const skip=["اسم الشخصية","العمر","اسمك في ديسكورد","اسم ماينكرافت","الصور"];
const det=x=>Object.entries(x.data||{}).filter(([k])=>!skip.includes(k)).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join(" · ");
