 sector_logos:{t:"شعارات القطاعات",f:[["s","القطاع","sec"],["u","رابط الصورة أو مسار الملف (مثال: images/police-logo.png)"]]},health_prices:{t:"أسعار الخدمات الصحية",f:[["n","الخدمة"],["p","السعر (رقم)"],["d","وصف (اختياري)"]]},
