function ac(inp,list,fetcher,render,pick){let t;inp.addEventListener("input",()=>{clearTimeout(t);const q=inp.value.trim();if(q.length<2){list.innerHTML="";return}t=setTimeout(async()=>{const r=await fetcher(q);list.innerHTML=r.length?r.map((x,i)=>`<div class="sg" data-i="${i}">${render(x)}</div>`).join(""):`<div class="sg" style="color:var(--mut)">لا توجد نتائج، يمكنك كتابة الاسم يدوياً</div>`;list.querySelectorAll("[data-i]").forEach(el=>el.onclick=()=>{pick(r[+el.dataset.i]);list.innerHTML=""})},220)})}
const cRender=c=>`<b>${esc(c.name)}</b> <span style="color:var(--mut);font-size:12px">· ${esc(c.national_id)} · @${esc(c.discord_name||"-")} · ${esc(c.mc_name||"-")}</span>`;
function addFine(sec="traffic",pre=null){const M=sec==="municipality",V=(CONFIG.violations||[]).filter(v=>M?v.s==="municipality":v.s!=="municipality");let c=pre;
 modal(M?"تسجيل مخالفة بلدية":"تسجيل مخالفة",`<form id="af"><label>المواطن (اكتب جزء من الاسم أو الديسكورد أو ماينكرافت أو رقم الهوية)</label><div class="sgw"><input id="aq" autocomplete="off" required><div class="sgb" id="aql"></div></div><div id="aqi" style="color:var(--mut);font-size:13px;margin-top:4px"></div><div id="avh"></div><label>المخالفات (الغرامة جاهزة لكل مخالفة)</label><input id="vf" placeholder="ابحث في المخالفات…" style="margin-bottom:6px"><div id="vl" style="max-height:210px;overflow:auto;border:1px solid var(--bd);border-radius:9px">${V.map((v,i)=>`<label class="vr" data-n="${esc(v.n)}"><input type="checkbox" data-i="${i}"> <span style="flex:1">${esc(v.n)}</span> <b>${v.a} ${CUR}</b></label>`).join("")||none("لا توجد مخالفات معرّفة، أضفها من لوحة الإدارة.")}</div><div style="margin:10px 0;font-weight:800">الإجمالي: <span id="tot">0</span> ${CUR}</div><button class="btn">حفظ المخالفة</button></form>`);
 const tot=()=>{$("#tot").textContent=[...document.querySelectorAll("#vl input:checked")].reduce((s,e)=>s+ +V[+e.dataset.i].a,0)};
 document.querySelectorAll("#vl input").forEach(e=>e.onchange=tot);
 $("#vf").oninput=e=>document.querySelectorAll("#vl .vr").forEach(l=>l.style.display=l.dataset.n.includes(e.target.value.trim())?"":"none");
 const veh=async x=>{c=x;$("#avh").innerHTML="";if(!x||M)return;const{data}=await sb.from("vehicles").select("*").eq("citizen_id",x.id);if((data||[]).length)$("#avh").innerHTML=`<label>المركبة (اختياري)</label><select id="avs"><option value="">بدون</option>${data.map(v=>`<option value="${esc(v.plate)}">${esc(v.plate)} — ${esc(v.model)}</option>`).join("")}</select>`};
 const inp=$("#aq");inp.addEventListener("input",()=>{veh(null);$("#aqi").textContent=""});
 ac(inp,$("#aql"),cSearch,cRender,x=>{inp.value=x.name;$("#aqi").textContent=`هوية ${x.national_id} · @${x.discord_name||"-"} · ${x.mc_name||"-"}`;veh(x)});
 if(pre){inp.value=pre.name;$("#aqi").textContent=`هوية ${pre.national_id}`;veh(pre)}
 $("#af").onsubmit=async e=>{e.preventDefault();const sel=[...document.querySelectorAll("#vl input:checked")].map(x=>V[+x.dataset.i]);if(!sel.length)return toast("اختر مخالفة واحدة على الأقل");
  const name=c?.name||inp.value.trim(),plate=$("#avs")?.value||"—",rows=sel.map(v=>({sector:M?"municipality":"traffic",citizen_id:c?.id??null,citizen_name:name,plate,discord_name:c?.discord_name||"",reason:v.n,amount:+v.a,officer_name:offN()})),{error}=await sb.from("fines").insert(rows);
  cl();toast(error?"تعذر الحفظ":"تم تسجيل المخالفة ✔");
  if(!error){notify(M?"municipality":"police","مخالفة جديدة",{"المواطن":name,"رقم الهوية":c?.national_id||"-","المخالفات":sel.map(v=>v.n+" ("+v.a+")").join("، "),"الإجمالي":rows.reduce((s,r)=>s+r.amount,0)+" "+CUR,"المسجّل":offN()});route()}}}
